export const e0 = ((inputs = {}, options = {}) => {
	void inputs;
	experimentalStaticLocale ?? options.locale ?? getLocale()
	return ("Save changes")
});

export const e1 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	return (`Hi ${i?.name}!`)
});

export const e2 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	return (`Disk is ${__paraglideRegistry.number("en", i?.ratio, { style: "percent" }, true)} full`)
});

export const e3 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	return (`Due ${__paraglideRegistry.datetime("en", i?.due, { dateStyle: "medium" }, true)}`)
});

export const e4 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	{
		const countPlural = __paraglideRegistry.plural("en", i?.count, {}, true);
		if (countPlural === "one") return (`${__paraglideRegistry.icuPound("en", i?.count, {})} file`);
		return (`${__paraglideRegistry.icuPound("en", i?.count, {})} files`)
	}
});

export const e5 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	{
		const countPlural = __paraglideRegistry.plural("en", i?.count, {}, true);
		const countPluralExact = i?.count;
		if ((countPluralExact === 0 || countPluralExact === "0")) return (`No messages`);
		if (countPlural === "one") return (`${__paraglideRegistry.icuPound("en", i?.count, {})} message from ${i?.name}`);
		return (`${__paraglideRegistry.icuPound("en", i?.count, {})} messages from ${i?.name}`)
	}
});

export const e6 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	{
		if (i?.role === "admin") return (`Manage team`);
		if (i?.role === "member") return (`View team`);
		return (`Request access`)
	}
});

export const e7 = ((i, options = {}) => {
	experimentalStaticLocale ?? options.locale ?? getLocale()
	{
		const countPlural = __paraglideRegistry.plural("en", i?.count, {}, true);
		if (i?.role === "admin" && countPlural === "one") return (`${__paraglideRegistry.icuPound("en", i?.count, {})} admin in ${i?.team}`);
		if (i?.role === "admin") return (`${__paraglideRegistry.icuPound("en", i?.count, {})} admins in ${i?.team}`);
		if (countPlural === "one") return (`${__paraglideRegistry.icuPound("en", i?.count, {})} member in ${i?.team}`);
		return (`${__paraglideRegistry.icuPound("en", i?.count, {})} members in ${i?.team}`)
	}
});
